package com.ias.ticket;

import com.ias.trust.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;

@RestController
public class Supplements {
 final Tickets t;final StaffAccess access;
 public Supplements(Tickets t,StaffAccess access){this.t=t;this.access=access;}
 Tickets.Actor actor(HttpServletRequest r,boolean reply){Chain.source(r);long deadline=Chain.deadline(r);var v=Chain.identity("ticket-identity",Chain.cookie(r),reply?"TICKET_CUSTOMER_SUPPLEMENT":"TICKET_WORK",r.getHeader("X-CSRF-TOKEN"),Chain.trace(r),deadline);Chain.fresh(v,deadline);return new Tickets.Actor(Tickets.id(v.get("tenantId")),Tickets.id(v.get("userId")),v.get("identityType").toString(),Chain.cookie(r),r.getHeader("X-CSRF-TOKEN"),Chain.trace(r),deadline,v.get("attempt").toString());}
 void fresh(Tickets.Actor a){Chain.fresh(Chain.identity("ticket-identity",a.token(),a.type().equals("CUSTOMER")?"TICKET_CUSTOMER_SUPPLEMENT":"TICKET_WORK",a.csrf(),a.trace(),a.deadline()),a.deadline());}
 Map<String,Object> fields(Map<String,Object>b,boolean reply){var required=reply?Set.of("expectedVersion","roundId","body","attachmentIds"):Set.of("expectedVersion","roundId","question");var allowed=new HashSet<>(required);if(!reply)allowed.add("assignmentId");if(!allowed.containsAll(b.keySet())||!b.keySet().containsAll(required)||!(b.get("expectedVersion") instanceof String))throw Tickets.bad();var data=new TreeMap<String,Object>(b);data.put("expectedVersion",Long.toString(Tickets.id(b.get("expectedVersion"))));Tickets.uuid(b.get("roundId"));Tickets.text(b.get(reply?"body":"question"),reply?1:5,reply?2000:500,true);if(b.containsKey("assignmentId"))Tickets.uuid(b.get("assignmentId"));if(reply){if(!(b.get("attachmentIds") instanceof List<?> list)||list.size()>5)throw Tickets.bad();var ids=list.stream().map(Tickets::uuid).sorted().toList();if(new HashSet<>(ids).size()!=ids.size())throw Tickets.bad();data.put("attachmentIds",ids);}return data;}
 @PostMapping("/api/ticket/tickets/{key}/supplement-requests") Map<String,Object> request(@PathVariable String key,@RequestBody Map<String,Object>b,HttpServletRequest r){return perform(key,null,fields(b,false),actor(r,false),Tickets.uuid(Chain.single(r,"Idempotency-Key")));}
 @PostMapping("/api/ticket/tickets/{key}/supplement-requests/{request}/reply") Map<String,Object> reply(@PathVariable String key,@PathVariable String request,@RequestBody Map<String,Object>b,HttpServletRequest r){var data=fields(b,true);data.put("requestId",Tickets.uuid(request));return perform(key,request,data,actor(r,true),Tickets.uuid(Chain.single(r,"Idempotency-Key")));}
 boolean mayRequest(Map<String,Object>f,Map<String,Object>row){return access.permission(f,"ticket.supplement.request")&&(access.company(f,row.get("company_id"))||"IN_PROGRESS".equals(row.get("status"))&&access.engineer(f,row)&&access.permission(f,"ticket.record"));}
 Map<String,Object> current(Map<String,Object>row,boolean lock){if(row.get("current_supplement_id")==null)return null;var rows=t.db.queryForList("SELECT * FROM ticket_supplement_request WHERE id=? AND ticket_id=? AND round_id=?"+(lock?" FOR UPDATE":""),row.get("current_supplement_id"),row.get("id"),row.get("round_id"));if(rows.isEmpty())throw new Problem(409,"SUPPLEMENT_NOT_CURRENT");return rows.getFirst();}
 Map<String,Object> customer(String key,String request,Tickets.Actor a,boolean lock){fresh(a);var row=t.accessible(key,a);if(!a.type().equals("CUSTOMER")||Tickets.id(row.get("reporter_user_id"))!=a.user())throw new Problem(404,"TARGET_NOT_ACCESSIBLE");if(!Objects.equals(row.get("current_supplement_id"),request))throw new Problem(409,"SUPPLEMENT_NOT_CURRENT");Workflow.state(row.get("status").toString(),"WAITING_INFORMATION");var req=current(row,lock);if(t.db.queryForObject("SELECT COUNT(*) FROM ticket_supplement_reply WHERE request_id=?",Long.class,request)>0)throw new Problem(409,"SUPPLEMENT_ALREADY_REPLIED");return req;}
 Map<String,Object> perform(String key,String request,Map<String,Object>b,Tickets.Actor a,String operation){Tickets.uuid(key);t.accessible(key,a);String action=request==null?"supplement-request":"supplement-reply",digest=Tickets.hash(b);
  return t.tx.execute(tx->{t.lockActor(a.tenant(),a.user());var row=t.db.queryForMap("SELECT * FROM ticket_record WHERE id=? AND tenant_id=? FOR UPDATE",key,a.tenant());fresh(a);t.accessible(key,a);Map<String,Object> facts=null;
   if(request==null){facts=access.facts(a);if(!access.permission(facts,"ticket.supplement.request"))throw new Problem(403,"ACCESS_DENIED");if(!access.company(facts,row.get("company_id"))&&!(access.engineer(facts,row)&&access.permission(facts,"ticket.record")))throw new Problem(404,"TARGET_NOT_ACCESSIBLE");}else if(!a.type().equals("CUSTOMER")||Tickets.id(row.get("reporter_user_id"))!=a.user())throw new Problem(404,"TARGET_NOT_ACCESSIBLE");
   var previous=t.db.queryForList("SELECT * FROM ticket_action_operation WHERE operation_id=? FOR UPDATE",operation);if(!previous.isEmpty()){var old=previous.getFirst();if(Tickets.id(old.get("tenant_id"))!=a.tenant()||Tickets.id(old.get("actor_user_id"))!=a.user()||!old.get("ticket_id").equals(key))throw new Problem(404,"OPERATION_NOT_FOUND");if(!action.equals(old.get("action"))||!digest.equals(old.get("request_digest")))throw new Problem(409,"IDEMPOTENCY_CONFLICT");return Tickets.json(old.get("result_json"));}
   StockExecutionBoundary.guard(t,key);if(!row.get("round_id").equals(b.get("roundId")))throw new Problem(409,"ROUND_CONFLICT");long version=Tickets.id(row.get("row_version"));if(version==Long.MAX_VALUE||version!=Tickets.id(b.get("expectedVersion")))throw new Problem(409,"VERSION_CONFLICT");if(row.get("assignment_id")!=null)t.db.queryForList("SELECT id FROM ticket_assignment WHERE id=? FOR UPDATE",row.get("assignment_id"));
   Instant time=new Completion(t,access).now();String record=UUID.randomUUID().toString(),reqId=request,replyId=null,next,resume,body;var result=new LinkedHashMap<String,Object>();
   if(request==null){String state=row.get("status").toString();if(!Set.of("PENDING_ACCEPTANCE","IN_PROGRESS").contains(state)||row.get("current_supplement_id")!=null)throw new Problem(409,"INVALID_STATE");if(state.equals("PENDING_ACCEPTANCE")){access.customerService(facts,row,"ticket.supplement.request");if(b.containsKey("assignmentId"))throw Tickets.bad();}else if(!Objects.equals(row.get("assignment_id"),b.get("assignmentId")))throw new Problem(409,"ASSIGNMENT_CONFLICT");
    reqId=UUID.randomUUID().toString();resume=state;body=b.get("question").toString();next="WAITING_INFORMATION";
    new Transfers(t,access).terminate(row,a,operation,"SUPPLEMENT_REQUESTED",time);t.db.update("INSERT INTO ticket_supplement_request(id,ticket_id,round_id,assignment_id,resume_state,operation_id,question,requested_by,requested_at) VALUES(?,?,?,?,?,?,?,?,?)",reqId,key,b.get("roundId"),row.get("assignment_id"),resume,operation,body,a.user(),Timestamp.from(time));
    t.db.update("UPDATE ticket_record SET current_supplement_id=? WHERE id=?",reqId,key);new Rounds(t).first(row,a,record,time,operation);result.put("requestedAt",time.toString());
   }else{var req=customer(key,request,a,true);resume=req.get("resume_state").toString();next=resume;replyId=UUID.randomUUID().toString();body=b.get("body").toString();
    t.db.update("INSERT INTO ticket_supplement_reply(id,request_id,ticket_id,round_id,operation_id,body,replied_by,replied_at) VALUES(?,?,?,?,?,?,?,?)",replyId,request,key,b.get("roundId"),operation,body,a.user(),Timestamp.from(time));
    for(Object id:(List<?>)b.get("attachmentIds")){var files=t.db.queryForList("SELECT * FROM ticket_file WHERE id=? FOR UPDATE",id);if(files.isEmpty())throw new Problem(400,"INVALID_SUPPLEMENT_FILES");var file=files.getFirst();if(!Objects.equals(file.get("supplement_ticket_id"),key)||!Objects.equals(file.get("supplement_request_id"),request)||!Objects.equals(file.get("supplement_round_id"),b.get("roundId"))||!Objects.equals(file.get("reply_operation_id"),operation)||Tickets.id(file.get("tenant_id"))!=a.tenant()||Tickets.id(file.get("user_id"))!=a.user()||!file.get("state").equals("READY"))throw new Problem(400,"INVALID_SUPPLEMENT_FILES");t.db.update("INSERT INTO ticket_file_reference(file_id,ticket_id) VALUES(?,?)",id,key);t.db.update("INSERT INTO ticket_supplement_file_reference(file_id,reply_id,request_id,ticket_id) VALUES(?,?,?,?)",id,replyId,request,key);}
    t.db.update("UPDATE ticket_record SET current_supplement_id=NULL WHERE id=?",key);result.put("replyId",replyId);result.put("repliedAt",time.toString());
   }
   t.db.update("INSERT INTO ticket_processing_record(id,ticket_id,round_id,assignment_id,operation_id,actor_user_id,type,body,work_hours,visibility,qualification_json,row_version,occurred_at) VALUES(?,?,?,?,?,?,?,?,0,'CUSTOMER_VISIBLE',?,?,?)",record,key,b.get("roundId"),row.get("assignment_id"),operation,a.user(),action.replace('-','_').toUpperCase(Locale.ROOT),body,Chain.JSON.writeValueAsString(facts==null?Map.of("identityType","CUSTOMER"):new Workflow(t,access).qualification(facts)),version+1,Timestamp.from(time));t.db.update("UPDATE ticket_record SET status=?,row_version=row_version+1 WHERE id=?",next,key);
   result.putAll(Map.of("operationId",operation,"action",action,"state","COMPLETED","ticketId",key,"requestId",reqId,"roundId",b.get("roundId"),"resumeState",resume,"status",next,"rowVersion",Long.toString(version+1),"recordId",record));result.put("assignmentId",row.get("assignment_id"));result.put("nextAction",request==null?"WAIT_CUSTOMER_SUPPLEMENT":resume.equals("PENDING_ACCEPTANCE")?"WAIT_STAFF_ACCEPT":"CONTINUE_PROCESSING");
   t.db.update("INSERT INTO ticket_action_operation(operation_id,tenant_id,actor_user_id,ticket_id,action,request_digest,result_json,created_at) VALUES(?,?,?,?,?,?,?,?)",operation,a.tenant(),a.user(),key,action,digest,Chain.JSON.writeValueAsString(result),Timestamp.from(time));t.db.update("INSERT INTO ticket_audit(operation_id,tenant_id,actor_user_id,action,occurred_at) VALUES(?,?,?,?,?)",operation,a.tenant(),a.user(),"WORKFLOW_"+action.replace('-','_').toUpperCase(Locale.ROOT),Timestamp.from(time));Chain.remaining(a.deadline());return result;
  });
 }
 Map<String,Object> view(Map<String,Object>req){var out=new LinkedHashMap<String,Object>();for(String[]p:new String[][]{{"requestId","id"},{"ticketId","ticket_id"},{"roundId","round_id"},{"assignmentId","assignment_id"},{"resumeState","resume_state"},{"question","question"}})out.put(p[0],req.get(p[1]));out.put("requestedBy",req.get("requested_by").toString());out.put("requestedAt",Tickets.utc(req.get("requested_at")));var replies=t.db.queryForList("SELECT * FROM ticket_supplement_reply WHERE request_id=?",req.get("id"));var termination=t.db.queryForList("SELECT cancelled_at FROM ticket_cancellation WHERE terminated_supplement_id=?",req.get("id"));out.put("termination",termination.isEmpty()?null:Map.of("reason","CANCELLED","terminatedAt",Tickets.utc(termination.getFirst().get("cancelled_at"))));out.put("state",!termination.isEmpty()?"CANCELLED":replies.isEmpty()?"OPEN":"REPLIED");out.put("reply",null);if(!replies.isEmpty()){var r=replies.getFirst();var reply=new LinkedHashMap<String,Object>();reply.putAll(Map.of("replyId",r.get("id"),"operationId",r.get("operation_id"),"body",r.get("body"),"repliedBy",r.get("replied_by").toString(),"repliedAt",Tickets.utc(r.get("replied_at"))));reply.put("attachments",t.db.queryForList("SELECT f.* FROM ticket_file f JOIN ticket_supplement_file_reference x ON x.file_id=f.id WHERE x.reply_id=? ORDER BY f.id",r.get("id")).stream().map(FileStore::dto).toList());out.put("reply",reply);}return out;}
 @GetMapping("/api/ticket/tickets/{key}/supplement-requests") Map<String,Object> history(@PathVariable String key,HttpServletRequest r){var a=t.actor(r,false);var visible=t.accessible(key,a);String selectedRound=new Rounds(t).selected(r,visible);for(var e:r.getParameterMap().entrySet())if(!Set.of("page","size","roundId").contains(e.getKey())||e.getValue().length!=1)throw Tickets.bad();long page=r.getParameter("page")==null?1:Tickets.id(r.getParameter("page")),size=r.getParameter("size")==null?20:Tickets.id(r.getParameter("size"));if(page>1000000||!Set.of(20L,50L,100L).contains(size))throw Tickets.bad();return Map.of("items",t.db.queryForList("SELECT * FROM ticket_supplement_request WHERE ticket_id=? AND round_id=? ORDER BY requested_at DESC,id DESC LIMIT ? OFFSET ?",key,selectedRound,size,(page-1)*size).stream().map(this::view).toList(),"total",t.db.queryForObject("SELECT COUNT(*) FROM ticket_supplement_request WHERE ticket_id=? AND round_id=?",Long.class,key,selectedRound),"page",page,"size",size);}
 void project(Map<String,Object>out,Map<String,Object>row,Tickets.Actor a){var req=current(row,false);out.put("currentSupplement",req==null?null:view(req));var actions=new ArrayList<String>((List<String>)out.get("allowedActions"));if(a.type().equals("CUSTOMER")){if(req!=null&&"WAITING_INFORMATION".equals(row.get("status")))actions.add("supplement-reply");}else if(Set.of("PENDING_ACCEPTANCE","IN_PROGRESS").contains(row.get("status"))&&mayRequest(access.facts(a),row))actions.add("supplement-request");out.put("allowedActions",actions);out.put("firstResponsePriority",row.get("first_response_priority"));out.put("firstResponseMet",row.get("first_response_at")==null?null:!Completion.instant(row.get("first_response_at")).isAfter(Completion.instant(row.get("response_due_at"))));}
}
